import{_ as a,o as s,c as t,a0 as o}from"./chunks/framework.BxCN1dRw.js";const g=JSON.parse('{"title":"跟做：外观与语言设置","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/appearance-language"},"headers":[],"relativePath":"tutorials/appearance-language.md","filePath":"tutorials/appearance-language.md"}'),i={name:"tutorials/appearance-language.md"};function n(c,e,r,l,d,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="跟做-外观与语言设置" tabindex="-1">跟做：外观与语言设置 <a class="header-anchor" href="#跟做-外观与语言设置" aria-label="Permalink to &quot;跟做：外观与语言设置&quot;">​</a></h1><p>界面语言和明暗主题是设备级偏好：登录前就能切换，选择保存在当前浏览器或桌面端，不跨设备同步，也不进入账号数据。本章走一遍偏好的完整行为——首访跟随设备、手动选择优先、刷新恢复、无效值回退、存储不可用时仍可切换——以及应用文案的双语归属规则：Core 与各示例各自维护目录，在组装点合并，运行时缺失翻译回退到可理解文案而不是裸 key。</p><h2 id="_1-先体验-从登录页到设置页" tabindex="-1">1. 先体验：从登录页到设置页 <a class="header-anchor" href="#_1-先体验-从登录页到设置页" aria-label="Permalink to &quot;1. 先体验：从登录页到设置页&quot;">​</a></h2><p>运行 <code>just dev</code>，打开 <code>/login</code>。右上角有「简体中文 / English」和「跟随系统 / 亮色 / 暗色」两组控件，登录前后行为一致：点击立即生效，页面不重载，正在输入的邮箱/密码原样保留。注册页、忘记/重置密码页使用同一组控件。</p><p>登录后侧栏底部进入「设置」（<code>/settings</code>）：语言和主题在「外观与语言」分区里，仍是两组原生单选框，与登录页控件写同一个偏好状态。切到 English 后侧栏、页面标题、<code>html.lang</code> 同步变为英文；地址栏没有变化，也没有网络请求——切换是纯前端状态。</p><p>设置页按分区组织：外观与语言（本设备）、账户、API Keys、设计系统（内嵌同一展厅）与帮助；后三类属于登录后能力，会话解析后出现。<code>?section=</code> 查询直达某个分区，例如 <code>/settings?section=api-keys</code>；侧栏底部只保留「设置」入口与登录后的高频直达（API Keys、设计系统、系统状态），使用教程在设置的「帮助」分区里。</p><h2 id="_2-偏好判定顺序" tabindex="-1">2. 偏好判定顺序 <a class="header-anchor" href="#_2-偏好判定顺序" aria-label="Permalink to &quot;2. 偏好判定顺序&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/packages/views/src/shell/preferences.tsx" target="_blank" rel="noreferrer">preferences 模块</a>实现三条规则：</p><ol><li><strong>首次使用跟随设备</strong>。读取 <code>navigator.languages</code> 按顺序找第一个中文或英文标签：中文（<code>zh-*</code>）→ 简体中文；英文（<code>en-*</code>）→ English；都没有 → English。<code>html.lang</code> 相应写 <code>zh-CN</code> 或 <code>en</code>。</li><li><strong>手动选择优先并保存</strong>。选择写入 <code>localStorage</code> 的 <code>saas.locale</code> 与 <code>saas.theme</code>；下次打开直接采用，不再看设备语言。</li><li><strong>无效值回退</strong>。存储里的值不在已知集合内（例如手工改过）时按&quot;未保存&quot;处理，回到第 1 条。</li></ol><p>主题默认「跟随系统」：只有该模式监听系统明暗变化并实时切换；「亮色 / 暗色」固定不变。</p><h2 id="_3-首屏不闪烁-绘制前的内联脚本" tabindex="-1">3. 首屏不闪烁：绘制前的内联脚本 <a class="header-anchor" href="#_3-首屏不闪烁-绘制前的内联脚本" aria-label="Permalink to &quot;3. 首屏不闪烁：绘制前的内联脚本&quot;">​</a></h2><p>React 首帧渲染之前，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/apps/web/index.html" target="_blank" rel="noreferrer">index.html</a> 的一段内联脚本读取同样的两个键，直接在 <code>&lt;html&gt;</code> 上设置 <code>lang</code>、<code>dark</code> class 和 <code>color-scheme</code>。这样刷新深色偏好时不会先白一帧。脚本逻辑与 <code>PreferencesProvider</code> 必须保持一致——两边都读同一个键、同一个回退顺序；改任一侧时同步另一侧。</p><p>存储不可用（隐私模式禁用存储等）时两个读取都静默失败：应用照常启动，偏好只在当前会话内有效，切换控件仍然工作。</p><h2 id="_4-双语文案按归属注册" tabindex="-1">4. 双语文案按归属注册 <a class="header-anchor" href="#_4-双语文案按归属注册" aria-label="Permalink to &quot;4. 双语文案按归属注册&quot;">​</a></h2><p>界面文案分两处维护：</p><ul><li><strong>Core 目录</strong>：<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/packages/views/src/shell/core-messages.ts" target="_blank" rel="noreferrer">core-messages.ts</a> 持有壳、首页、身份流程、设置、错误与通用提示的中英文案。发布完整性由对齐测试保证——中英 key 集合一致、无空值、占位符一致。</li><li><strong>示例目录</strong>：每个示例在自己的 <code>ExampleContribution.messages</code> 里提供双语文案，键以示例 id 命名空间开头（如 <code>notes.page.title</code>）。</li></ul><p>组装时 Core 先注册，示例随后追加；示例占用他人已注册的 key 会在组装时报错，不会静默覆盖。页面通过 <code>useAppMessage()</code>（或带命名空间的 <code>useAppMessage(&#39;notes&#39;)</code>）解析：当前语言缺失时回退英文，再缺失时显示&quot;这段界面文字暂不可用。&quot;之类的可理解提示——永不显示裸 key，也不抛错。<code>{name}</code> 形式的参数插值由共享解析器完成。</p><p>日期与数字用当前语言的 <code>Intl.DateTimeFormat</code> / <code>Intl.NumberFormat</code> 格式化（<code>useAppFormat</code>），时区沿用设备设置。设置页底部的教程链接按当前语言打开本章的对应深链（中文 <code>/docs/</code>、英文 <code>/en/docs/</code>，站点 base 参与拼路径）。</p><h2 id="_5-无障碍与窄屏" tabindex="-1">5. 无障碍与窄屏 <a class="header-anchor" href="#_5-无障碍与窄屏" aria-label="Permalink to &quot;5. 无障碍与窄屏&quot;">​</a></h2><p>语言和主题控件是真实按钮（<code>aria-pressed</code> 标注当前项），设置页用原生 <code>fieldset/legend</code> 单选框，键盘行为跟随平台。切换语言时 <code>html.lang</code>、页面 <code>&lt;title&gt;</code> 与 meta description、导航的无障碍名称（&quot;主菜单 / Main menu&quot;）一并更新。侧栏在窄屏折叠为抽屉，开合按钮用 <code>aria-expanded</code> / <code>aria-controls</code> 声明状态，Esc 也会收起；窄屏触控目标保持不小于 44px，桌面行高压至 36px。通知与 API Keys 属于登录后能力，未登录的侧栏不展示。</p><h2 id="_6-验证" tabindex="-1">6. 验证 <a class="header-anchor" href="#_6-验证" aria-label="Permalink to &quot;6. 验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/views/src/shell/preferences.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/views/src/shell/core-messages.test.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/settings.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>偏好测试覆盖设备语言顺序、主题解析、持久化、无效值回退、系统主题联动与存储不可用；Core 目录测试做中英对齐检查；settings 测试在真实 Router 里走切换、持久化与输入不丢失。浏览器验证集中在一次：首屏主题、刷新恢复、系统明暗切换与窄屏抽屉。移除任一示例后本章能力不受影响——偏好与 Core 文案不属于任何示例。</p><hr><p>源码版本：<code>68f0788f4b1a</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/docs/tutorials/28-appearance-language.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,25)])])}const k=a(i,[["render",n]]);export{g as __pageData,k as default};
